

int fwd(void)
{
    int a = 1, b = 2, c = 3, d = 4, e = 5, f = 6, g = 7, h = 8;
    return a + b + c + d + e + f + g + h;
}

int rev(void)
{
    int h = 8, g = 7, f = 6, e = 5, d = 4, c = 3, b = 2, a = 1;
    return a + b + c + d + e + f + g + h;
}

int names(void)
{
    int count = 1, total = 2, index = 3, value = 4, width = 5, height = 6;
    return count + total + index + value + width + height;
}



























